import json,difflib
ctx=json.load(open('work/focused-successor/context-authoring-raw.json',encoding='utf-8'))
prop=json.load(open('work/focused-successor/specialist-proposal.json',encoding='utf-8'))
r2=json.load(open('work/criteria-review-01/specialist-proposal-r2.json',encoding='utf-8'))
cc=json.load(open('work/export-review-01/caller-comparison.json',encoding='utf-8'))
val_hashes={"authoring-01.delivery.q.continuity":"6df7e20ca123e5df9d02960a3c5413b8c3b0b4824ac14dcba5dba3e25b59a84b"}  # spot check vs pixl_validate above
ctx_by={c['id']:c for c in ctx['criteria']}
map_by={m['original_id']:m for m in prop['mapping']}
r2_by={c['criterion']:c for c in r2['criteria']}
cc_by={c['criterion']:c for c in cc['criterion_comparisons']}
allok=True
for i,c in ctx_by.items():
    m=map_by[i]; ck=c['fields']['ck']; rh=c['record_sha256']
    ok_h = rh==m['record_sha256']==r2_by[i]['record_sha256']==cc_by[i]['record_sha256']
    ok_c = ck==m['original_check']==r2_by[i]['original_check']
    dm=c['fields']['dm']['$symbol']; md=c['fields']['md']['$symbol']
    ok_dm = [dm,md]==m['original_domain_mode']
    if not(ok_h and ok_c and ok_dm): allok=False; print("XX",i,ok_h,ok_c,ok_dm)
print("ALL 20 ids/hashes/checks/domain-mode consistent across context, mapping, r2, caller-comparison:",allok)
print("\n== r2 proposed_check -> successor check: word-level delta per carried pair")
sc_by={c['id']:c for c in prop['criteria']}
for c in prop['criteria']:
    for k in c.get('carries') or []:
        pc=r2_by[k['id']]['proposed_check']
        a=pc.split(); b=c['check'].split()
        sm=difflib.SequenceMatcher(None,a,b)
        adds=[];dels=[]
        for tag,i1,i2,j1,j2 in sm.get_opcodes():
